-- COMPANION-PUBLISH-REPAIR-1 (personal-companion 1.17.0, 2026-10-13, pillar personal). reading.q08.org published nothing for 73h
-- (companion_runs 4549-5339). Two failure modes found while measuring the stall, each fixed in the PR that carries this file:
-- 1. companion-draft-cache-replay: the writer's Workers AI calls went through the default AI Gateway with its cache on, so an hourly
--    retry with the same prompt got the same draft back in 0.1 s and failed for the same reasons (runs 5242-5254 and 5264-5276 replayed
--    the 01:00Z drafts verbatim). Fixed by gateway skipCache on every writer and critic call.
-- 2. companion-gate-discards-repairable: drafts were thrown away for problems a deletion fixes (a banned phrase: 32 attempts in 72h; a
--    fact-check item that was the piece's own reasoning, or one quoted sentence: run 5334) and the notes critic scored a placeholder
--    objection (run 5329). Fixed by the deterministic banned-phrase repair, FACT/INFERENCE labels with the quoted-sentence prune and full
--    re-verification, and the notes critic reading the body for its objection. Accuracy stays fail-closed for FACT items.
-- Both detectors read the companion's own hourly stall metric in qnfo-audit (the companion_runs table lives in the private personal D1,
-- which a public probe log must not read): no piece for 36 hours means one of these, or a new cause, is back.
-- Idempotent (INSERT OR IGNORE).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-companion-draft-cache-replay', 'fm-companion-gate-discards-repairable'); DELETE FROM failure_modes WHERE fm_key IN ('companion-draft-cache-replay', 'companion-gate-discards-repairable');
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('companion-draft-cache-replay', 'personal-companion retries replayed the same cached draft and failed for the same reasons every hour', 'callWorkersAI ran through the default AI Gateway without skipCache; identical writer prompts (same topic, same feedback) were answered from the gateway cache', 'personal-companion 1.17.0: gateway skipCache on every writer and critic call', 'metric companion_hours_since_last_piece < 36', 'fm-companion-draft-cache-replay', '2026-10-13', NULL, 'a generation retry with the same topic and feedback while the DeepSeek writer is unavailable', 'companion_runs: compose stage rows a few hundred ms apart with drafts identical to the previous hour', 'reading.q08.org and its subscribers: no piece while the replayed draft fails'),
 ('companion-gate-discards-repairable', 'personal-companion discarded drafts whose only faults a deletion would fix', 'the repair covered grounding problems only; banned phrases, fact-check items that were reasoning or one quoted sentence, and the notes placeholder objection scored by the critic each rejected the whole draft', 'personal-companion 1.17.0: banned-phrase sentence deletion, cleaned draft to the extend path, FACT/INFERENCE labels, quoted-sentence prune with full re-verification, notes objection not gated', 'metric companion_hours_since_last_piece < 36', 'fm-companion-gate-discards-repairable', '2026-10-13', NULL, 'the Workers AI fallback writes the drafts (DeepSeek breaker open)', 'companion_runs rejected rows with banned:, critique objection= on notes, or fact-check items that are reasoning', 'reading.q08.org and its subscribers: no piece for days');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-companion-draft-cache-replay', NULL, 'COMPANION-PUBLISH-REPAIR-1', 'failure-mode detector', 'SELECT ''1'' AS expected, CASE WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''companion_hours_since_last_piece'') AS REAL) < 36 THEN ''1'' ELSE ''0'' END AS observed', 'd1-query', 3, 'personal-companion', 1, 'holding', 'failure-mode', 45000, 5, 0),
 ('fm-companion-gate-discards-repairable', NULL, 'COMPANION-PUBLISH-REPAIR-1', 'failure-mode detector', 'SELECT ''1'' AS expected, CASE WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''companion_hours_since_last_piece'') AS REAL) < 36 THEN ''1'' ELSE ''0'' END AS observed', 'd1-query', 3, 'personal-companion', 1, 'holding', 'failure-mode', 45000, 5, 0);
